import{_ as i,a0 as a,w as n,s as l,ao as T,I as s,x as e,a1 as p,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse('{"title":"IoT 网络安全：后备计划是什么？ | LCTT x X-CMD","titleTemplate":false,"description":"IoT 网络安全：后备计划是什么？ | LCTT (201710) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"IoT 网络安全：后备计划是什么？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"IoT 网络安全：后备计划是什么？ | LCTT (201710) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201710/20171018 IoT Cybersecurity what is plan b","title":"IoT 网络安全：后备计划是什么？","tag":"201710","desc":""},"relativePath":"201710/20171018 IoT Cybersecurity what is plan b.md","filePath":"[post].md"}'),u={name:"201710/20171018 IoT Cybersecurity what is plan b.md"};function m(d,t,f,C,b,w){const o=a("Link");return n(),l("div",null,[t[13]||(t[13]=T('<h1 id="iot-网络安全-后备计划是什么" tabindex="-1">IoT 网络安全：后备计划是什么？ <a class="header-anchor" href="#iot-网络安全-后备计划是什么" aria-label="Permalink to “IoT 网络安全：后备计划是什么？”">​</a></h1><p>八月份，四名美国参议员提出了一项旨在改善物联网（IoT）安全性的法案。2017 年的 “物联网网络安全改进法” 是一项小幅的立法。它没有规范物联网市场。它没有任何特别关注的行业，或强制任何公司做任何事情。甚至没有修改嵌入式软件的法律责任。无论安全多么糟糕，公司可以继续销售物联网设备。</p><p>法案的做法是利用政府的购买力推动市场：政府购买的任何物联网产品都必须符合最低安全标准。它要求供应商确保设备不仅可以打补丁，而且是以认证和及时的方式进行修补，没有不可更改的默认密码，并且没有已知的漏洞。这是一个你可以达到的低安全值，并且将大大提高安全性，可以说明关于物联网安全性的当前状态。（全面披露：我帮助起草了一些法案的安全性要求。）</p><p>该法案还将修改“计算机欺诈和滥用”和“数字千年版权”法案，以便安全研究人员研究政府购买的物联网设备的安全性。这比我们的行业需求要窄得多。但这是一个很好的第一步，这可能是对这个立法最好的事。</p><p>不过，这一步甚至不可能施行。我在八月份写这个专栏，毫无疑问，这个法案你在十月份或以后读的时候会没有了。如果听证会举行，它们无关紧要。该法案不会被任何委员会投票，不会在任何立法日程上。这个法案成为法律的可能性是零。这不仅仅是因为目前的政治 - 我在奥巴马政府下同样悲观。</p><p>但情况很严重。互联网是危险的 - 物联网不仅给了眼睛和耳朵，而且还给手脚。一旦有影响到位和字节的安全漏洞、利用和攻击现在将会影响到其血肉。</p><p>正如我们在过去一个世纪一再学到的那样，市场是改善产品和服务安全的可怕机制。汽车、食品、餐厅、飞机、火灾和金融仪器安全都是如此。原因很复杂，但基本上卖家不会在安全方面进行竞争，因为买方无法根据安全考虑有效区分产品。市场使用的竞相降低门槛的机制价格降到最低的同时也将质量降至最低。没有政府干预，物联网仍然会很不安全。</p><p>美国政府对干预没有兴趣，所以我们不会看到严肃的安全和保障法规、新的联邦机构或更好的责任法。我们可能在欧盟有更好的机会。根据“通用数据保护条例”在数据隐私的规定，欧盟可能会在 5 年内通过类似的安全法。没有其他国家有足够的市场份额来做改变。</p><p>有时我们可以选择不使用物联网，但是这个选择变得越来越少见了。去年，我试着不连接网络来购买新车但是失败了。再过几年, 就几乎不可能不连接到物联网。我们最大的安全风险将不会来自我们与之有市场关系的设备，而是来自其他人的汽车、照相机、路由器、无人机等等。</p><p>我们可以尝试为理想买单，并要求更多的安全性，但企业不会在物联网安全方面进行竞争 - 而且我们的安全专家不是一个可以产生影响的足够大的市场力量。</p><p>我们需要一个后备计划，虽然我不知道是什么。如果你有任何想法请评论。</p><p>这篇文章以前出现在 9/10 月的 《IEEE 安全与隐私》上。</p><hr><p>作者简介：</p><p>自从 2004 年以来，我一直在博客上写关于安全的文章，以及从 1998 年以来我的每月订阅中也有。我写书、文章和学术论文。目前我是 IBM Resilient 的首席技术官，哈佛伯克曼中心的研究员，EFF 的董事会成员。</p><hr>',16)),s("p",null,[t[1]||(t[1]=e("via: ",-1)),p(o,{href:"https://www.schneier.com/blog/archives/2017/10/iot_cybersecuri.html"},{default:r(()=>[...t[0]||(t[0]=[e("https://www.schneier.com/blog/archives/2017/10/iot_cybersecuri.html",-1)])]),_:1})]),s("p",null,[t[5]||(t[5]=e("作者：",-1)),p(o,{href:"https://www.schneier.com/blog/about/"},{default:r(()=>[...t[2]||(t[2]=[e("Bruce Schneier",-1)])]),_:1}),t[6]||(t[6]=e(" 译者：",-1)),p(o,{href:"https://github.com/geekpi"},{default:r(()=>[...t[3]||(t[3]=[e("geekpi",-1)])]),_:1}),t[7]||(t[7]=e(" 校对：",-1)),p(o,{href:"https://github.com/wxy"},{default:r(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[10]||(t[10]=e("本文由 ",-1)),p(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原创编译，",-1)),p(o,{href:"https://linux.cn/"},{default:r(()=>[...t[9]||(t[9]=[e("Linux中国",-1)])]),_:1}),t[12]||(t[12]=e(" 荣誉推出",-1))])])}const h=i(u,[["render",m]]);export{g as __pageData,h as default};
